// Auth Context
'use client'

import React, { createContext, useContext, useEffect, useState } from 'react'
import { User, Session, AuthChangeEvent } from '@supabase/supabase-js'
import { supabase, isAdmin as checkIsAdmin } from '@/lib/supabase'

interface AuthContextType {
  user: User | null
  session: Session | null
  loading: boolean
  isAdmin: boolean
  signIn: (email: string, password: string) => Promise<any>
  signUp: (email: string, password: string) => Promise<any>
  signOut: () => Promise<any>
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export const useAuth = () => {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null)
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)
  const [isAdmin, setIsAdmin] = useState(false)

  useEffect(() => {
    let mounted = true
    let subscription: any = null

    // Simple session check
    const checkSession = async () => {
      try {
        if (!supabase) {
          console.error('❌ Supabase not available')
          console.error('📋 .env.local dosyasını kontrol edin: NEXT_PUBLIC_SUPABASE_URL ve NEXT_PUBLIC_SUPABASE_ANON_KEY')
          if (mounted) setLoading(false)
          return
        }

        // Database bağlantı kontrolü
        const { data: { session }, error } = await supabase.auth.getSession()

        if (!mounted) return

        if (error) {
          console.error('❌ Session error:', error.message || error)
          if (error.message?.includes('JWT') || error.message?.includes('token')) {
            console.error('🔍 Token hatası - Supabase bağlantısını kontrol edin')
          }
        } else {
          console.log('✅ Session loaded:', session?.user?.email || 'No session')
          if (mounted) {
            setSession(session)
            setUser(session?.user ?? null)

            if (session?.user) {
              // Admin check'i sadece bir kez yap
              try {
                const adminStatus = await checkIsAdmin()
                if (mounted) {
                  console.log('🔐 Initial admin check:', session.user.email, '=', adminStatus ? '✅ ADMIN' : '❌ NOT ADMIN')
                  setIsAdmin(adminStatus)
                }
              } catch (adminError: any) {
                console.error('❌ Admin check failed:', adminError?.message || adminError)
                if (mounted) setIsAdmin(false)
              }
            } else {
              if (mounted) setIsAdmin(false)
            }
          }
        }
      } catch (error: any) {
        console.error('❌ Session check error:', error?.message || error)
        console.error('🔍 Hata detayları:', error)
      } finally {
        if (mounted) setLoading(false)
      }
    }

    checkSession()

    // Listen for auth state changes - ama admin check'i sadece SIGNED_IN'de yap
    if (supabase) {
      const { data } = supabase.auth.onAuthStateChange(async (event: AuthChangeEvent, session: Session | null) => {
        if (!mounted) return

        console.log('Auth state changed:', event, session?.user?.email || 'No user')
        
        if (event === 'SIGNED_IN') {
          // Sadece SIGNED_IN'de admin check yap (TOKEN_REFRESHED'de yapma - sonsuz döngüye neden olur)
          if (mounted) {
            setSession(session)
            setUser(session?.user ?? null)
            
            if (session?.user) {
              const adminStatus = await checkIsAdmin()
              if (mounted) {
                console.log('Auth change - admin check:', session.user.email, '=', adminStatus ? 'ADMIN ✅' : 'NOT ADMIN ❌')
                setIsAdmin(adminStatus)
              }
            }
          }
        } else if (event === 'TOKEN_REFRESHED') {
          // Token refresh'te sadece session'ı güncelle, admin check yapma
          if (mounted) {
            setSession(session)
            setUser(session?.user ?? null)
            // Admin status'u değiştirme - zaten biliyoruz
          }
        } else if (event === 'SIGNED_OUT') {
          if (mounted) {
            setSession(null)
            setUser(null)
            setIsAdmin(false)
          }
        }
      })
      subscription = data.subscription
    }

    return () => {
      mounted = false
      subscription?.unsubscribe()
    }
  }, []) // Boş dependency array - sadece mount'ta çalış

  const signIn = async (email: string, password: string) => {
    try {
      if (!supabase) {
        return { error: { message: 'Supabase client not initialized' } }
      }

      const result = await supabase.auth.signInWithPassword({ email, password })

      if (!result.error && result.data?.user) {
        // Manually update state after successful login
        setUser(result.data.user)
        setSession(result.data.session)

        // Check admin status
        const adminStatus = await checkIsAdmin()
        setIsAdmin(adminStatus)
      }

      return result
    } catch (error) {
      console.error('Sign in error:', error)
      return { error: { message: 'An unexpected error occurred during sign in' } }
    }
  }

  const signUp = async (email: string, password: string) => {
    try {
      if (!supabase) {
        return { error: { message: 'Supabase client not initialized' } }
      }

      const result = await supabase.auth.signUp({ email, password })
      return result
    } catch (error) {
      console.error('Sign up error:', error)
      return { error: { message: 'An unexpected error occurred during sign up' } }
    }
  }

  const signOut = async () => {
    try {
      if (!supabase) {
        return { error: { message: 'Supabase client not initialized' } }
      }

      const result = await supabase.auth.signOut()

      if (!result.error) {
        // Manually clear state
        setUser(null)
        setSession(null)
        setIsAdmin(false)
      }

      return result
    } catch (error) {
      console.error('Sign out error:', error)
      return { error: { message: 'An unexpected error occurred during sign out' } }
    }
  }

  const value = {
    user,
    session,
    loading,
    isAdmin,
    signIn,
    signUp,
    signOut,
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}